let registry=fs.existsSync(path.join(root,'QA/registry.json'))?JSON.parse(read('QA/registry.json')):{version:1,entries:{}};
function allocate(prefix,key){if(registry.entries[key]&&!cases.some(c=>c.id===registry.entries[key]))return registry.entries[key];let n=1;const used=new Set([...Object.values(registry.entries),...cases.map(c=>c.id)]);while(used.has(`${prefix}-${String(n).padStart(3,'0')}`))n++;return registry.entries[key]=`${prefix}-${String(n).padStart(3,'0')}`;}
const cases=[];
function add(id,module,feature,description,layer,role,priority='P1',auto='YES',coverage='None',status='NOT RUN',issue='—',source=''){if(cases.some(x=>x.id===id))return;cases.push({id,module,feature,description,layer,role,priority,auto,coverage,status,issue,source});}
for(const issue of issues)add(issue.test,moduleForController(path.basename(issue.file,'.cs')),issue.title,issue.regression,issue.id==='BUG-FUNC-0004'?'Static analysis':issue.test.startsWith('UI-')?'Browser/component':issue.test.includes('SECURITY')?'HTTP security':issue.test.includes('FORM')?'Browser + HTTP':'Integration/rule','See issue reproduction',issue.priority,'YES',issue.observed?'Configured ESLint':'Static finding; regression absent',issue.observed?'FAIL':'NOT RUN',issue.id,src(issue.file,issue.needle));
