 const description=`${e.method} ${e.route}; invoke ${e.name} with its declared contract; ${writeOp?'assert exact committed/unchanged rows in fresh context and intended response body (including deliberate empty responses)':'assert returned scoped rows/fields, ordering and empty result'}; cover guards traced at source; nullable/invalid relation cases only where contract applies. Data sets: ${e.dbSets.join(', ')||'Identity or no domain store'}.`;
 add(id,mod,e.name,description,writeOp?'HTTP + SQL + serialization':'HTTP contract',e.academyFilter?`Admin/permission ${e.permission}; deny wrong tenant`:'Action-specific user/role checks',priority,'YES','No full-pipeline coverage','NOT RUN',related,`${e.file}:${e.line}`);
